// Dump the SD pricing user-exit and VOFM pricing-routine sources to files for the note agents.
// Usage: node dump-pricing-source.mjs <workspaceRoot>
import { readFileSync, writeFileSync, mkdirSync } from 'fs';
import { join } from 'path';
import { pathToFileURL } from 'url';

const root = process.argv[2];
const plugin = 'C:/Users/pssps/.claude/plugins/cache/sc4sap/sc4sap/0.6.35/scripts/config/sap-reader.mjs';
const { connect } = await import(pathToFileURL(plugin).href);
const base = join(root, '.sc4sap/work/HKT-DEV');
const out = join(base, 'config-docs/SD/source');
mkdirSync(out, { recursive: true });
const cust = JSON.parse(readFileSync(join(base, 'customizations/SD/enhancements.json'), 'utf8'));

const c = await connect('dump-pricing-source');
async function get(name) {
  const res = await c.callTool({ name: 'GetInclude', arguments: { include_name: name } });
  const text = res?.content?.[0]?.text ?? '';
  if (res?.isError) throw new Error(text.slice(0, 200));
  let src = text;
  try { const j = JSON.parse(text); src = j.source ?? j.code ?? j.content ?? text; } catch {}
  return String(src);
}

const index = [];
async function save(name, why) {
  try {
    const src = await get(name);
    writeFileSync(join(out, `${name.toLowerCase()}.abap`), src);
    index.push({ name, why, lines: src.split('\n').length });
    process.stderr.write(`ok ${name}\n`);
    return src;
  } catch (e) {
    index.push({ name, why, error: String(e.message) });
    process.stderr.write(`fail ${name}: ${e.message}\n`);
    return '';
  }
}

// User-exit frames, then the Z includes inside their pricing forms.
const PRICING_FORMS = /FORM\s+userexit_pricing_[a-z_]+/i;
for (const frame of ['MV45AFZZ', 'RV60AFZZ', 'RV60AFZC']) {
  const src = await save(frame, 'user-exit frame');
  let inPricing = false;
  for (const line of src.split('\n')) {
    if (/^\s*FORM\s+/i.test(line)) inPricing = PRICING_FORMS.test(line);
    if (/^\s*ENDFORM/i.test(line)) inPricing = false;
    const m = inPricing && /^\s*INCLUDE\s+([zy][a-z0-9_]+)/i.exec(line);
    if (m) await save(m[1].toUpperCase(), `${frame} pricing exit`);
  }
}
// VOFM pricing routines: requirements, formulas, scale base.
for (const r of cust.vofmRoutines.filter((v) => ['PBED', 'PFRA', 'PFRM', 'PSTK'].includes(v.group))) {
  await save(r.include, `VOFM ${r.group} ${r.number} ${r.description}`);
}
writeFileSync(join(out, 'index.json'), JSON.stringify(index, null, 1));
console.log(JSON.stringify({ ok: true, dir: out, files: index.filter((i) => !i.error).length, failed: index.filter((i) => i.error).length }));
await c.close();

