// Usage: node dump-exit-includes.mjs <workspaceRoot>
import { readFileSync, writeFileSync, existsSync } from 'fs';
import { join } from 'path';
import { pathToFileURL } from 'url';

const root = process.argv[2];
const plugin = 'C:/Users/pssps/.claude/plugins/cache/sc4sap/sc4sap/0.6.35/scripts/config/sap-reader.mjs';
const { connect } = await import(pathToFileURL(plugin).href);
const base = join(root, '.sc4sap/work/HKT-DEV');
const out = join(base, 'config-docs/SD/source');
const cust = JSON.parse(readFileSync(join(base, 'customizations/SD/enhancements.json'), 'utf8'));
const indexFile = join(out, 'index.json');
const index = JSON.parse(readFileSync(indexFile, 'utf8'));

const c = await connect('dump-exit-includes');
async function save(name, why) {
  const file = join(out, `${name.toLowerCase()}.abap`);
  if (existsSync(file)) return;
  try {
    const res = await c.callTool({ name: 'GetInclude', arguments: { include_name: name } });
    const text = res?.content?.[0]?.text ?? '';
    if (res?.isError) throw new Error(text.slice(0, 200));
    let src = text;
    try { const j = JSON.parse(text); src = j.source ?? j.code ?? j.content ?? text; } catch {}
    writeFileSync(file, String(src));
    index.push({ name, why, lines: String(src).split('\n').length });
  } catch (e) {
    index.push({ name, why, error: String(e.message) });
    process.stderr.write(`fail ${name}: ${e.message}\n`);
  }
}
for (const f of cust.formBasedExits) {
  await save(f.include, 'user-exit frame');
  for (const z of f.zIncludes || []) await save(z, `${f.include} exit`);
}
writeFileSync(indexFile, JSON.stringify(index, null, 1));
console.log(JSON.stringify({ ok: true, files: index.filter((i) => !i.error).length, failed: index.filter((i) => i.error).length }));
await c.close();

